head.script:
// 테스트 설명, 유효성 값 설정
scwin.tData = {
    "description" : "[calendar > E > oncancel]<br/>Calendar 컴포넌트에서 취소 버튼을 클릭할 때 발생합니다.",
    "validation" : [
        "Calendar 컴포넌트에서 취소 버튼을 클릭할 때 oncancel 이벤트가 발생합니다.",               
    ]
}



scwin.onpageload = function () {
    wf_body_left.getObj("scwin").createValidation(scwin.tData);

    // Global DataList 생성 호출
    $c.gcm.createCommonDatalist();

    // comp 초기 생성
    scwin.comp_init();
};



// comp 생성
scwin.comp_init = async function () {
    // 기존 target 있으면 삭제
    if (typeof target1 !== 'undefined') {
        target1.remove();
    }

    // 라벨: 수동 테스트 안내
    $c.gcm.createLabel('label="[수동 테스트 안내] 표시된 취소 버튼을 클릭하면 oncancel 이벤트가 발생합니다."', '', 'label1');

    // 취소 버튼이 표시되도록 고정 (calendarValueType=yearMonthDate + cancelButtonShow=true + cancelButtonHide=false)
    let properties = {
        calendarValueType : "yearMonthDate",
        cancelButtonShow : "true",
        cancelButtonHide : "false"
    }

    let cList = $c.gcm.createCList(properties);
    let eList = $c.gcm.createEList(["oncancel"]);

    await $c.gcm.createBasicCalendar(cList, eList);
}



// 취소 버튼 클릭 시 oncancel 이벤트 발생 (validation 1, 2, 3, 4)
scwin.target1_oncancel = function (e) {
    wf_body_bottom.getObj("scwin").setReturnValue("[oncancel 발생] 취소 버튼 클릭 → oncancel 핸들러 실행됨");    
};
